insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('BE', 'reverse_charge', 'reverse_charge', 'Autoliquidation — taxe à acquitter par le cocontractant.', '{"de":"Steuerschuldnerschaft des Leistungsempfängers.","en":"Reverse charge — VAT to be accounted for by the customer.","nl":"Btw verlegd — belasting te voldoen door de medecontractant."}'::jsonb, 10, date '1970-01-01', null, 'Arrêté royal n° 1 du 29 décembre 1992, art. 20'),
  ('BE', 'intracom_goods', 'intra_eu_goods', 'Livraison intracommunautaire exonérée — autoliquidation par l''acquéreur.', '{"de":"Steuerfreie innergemeinschaftliche Lieferung — Steuerschuldnerschaft des Erwerbers.","en":"Exempt intra-Community supply — reverse charge by the customer.","nl":"Vrijgestelde intracommunautaire levering — btw verlegd naar de afnemer."}'::jsonb, 20, date '1970-01-01', null, 'Code de la TVA, art. 39bis'),
  ('BE', 'intracom_services', 'intra_eu_services', 'Autoliquidation — TVA due par le preneur.', '{"de":"Steuerschuldnerschaft des Leistungsempfängers.","en":"Reverse charge — VAT due by the customer.","nl":"Btw verlegd — belasting verschuldigd door de afnemer."}'::jsonb, 30, date '1970-01-01', null, 'Code de la TVA, art. 21, § 2 ; directive 2006/112/CE, art. 44 et 196'),
  ('BE', 'export', 'export', 'Exportation exonérée de TVA.', '{"de":"Von der Mehrwertsteuer befreite Ausfuhr.","en":"Export exempt from VAT.","nl":"Uitvoer vrijgesteld van btw."}'::jsonb, 40, date '1970-01-01', null, 'Code de la TVA, art. 39'),
  ('BE', 'small_business', 'small_business', 'Régime particulier de franchise des petites entreprises — TVA non applicable.', '{"de":"Sonderregelung der Steuerbefreiung für Kleinunternehmen — Mehrwertsteuer nicht anwendbar.","en":"Special exemption scheme for small businesses — VAT not applicable.","nl":"Bijzondere vrijstellingsregeling voor kleine ondernemingen — btw niet van toepassing."}'::jsonb, 50, date '1970-01-01', null, 'Code de la TVA, art. 56bis'),
  ('BE', 'late_payment', 'late_payment', 'À défaut de paiement à l''échéance, un intérêt au taux légal applicable aux transactions commerciales et une indemnité forfaitaire de 40 € pour frais de recouvrement sont dus de plein droit et sans mise en demeure.', '{"de":"Bei Nichtzahlung bei Fälligkeit sind von Rechts wegen und ohne Mahnung Zinsen zum gesetzlichen Zinssatz für Handelsgeschäfte sowie eine Pauschalentschädigung von 40 € für Beitreibungskosten geschuldet.","en":"If payment is not made by the due date, interest at the statutory rate for commercial transactions and a fixed indemnity of 40 € for recovery costs are due by operation of law and without any reminder.","nl":"Bij niet-betaling op de vervaldag zijn van rechtswege en zonder ingebrekestelling een interest tegen de wettelijke rentevoet voor handelstransacties en een forfaitaire vergoeding van 40 € voor invorderingskosten verschuldigd."}'::jsonb, 60, date '1970-01-01', null, 'Loi du 2 août 2002 concernant la lutte contre le retard de paiement dans les transactions commerciales, art. 5 et 6')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
